class Account
{
public:
    long long balance() const { return m_balance; }

    bool deposit(long long cents)
    {
        if (cents <= 0)
        {
            return false;
        }
        m_balance += cents;
        return true;
    }

protected:
    void adjust(long long cents) { m_balance += cents; }

private:
    long long m_balance{ 0 };
};

class SavingsAccount : public Account
{
public:
    explicit SavingsAccount(double yearlyRatePercent) : m_rate{ yearlyRatePercent } {}

    void addMonthlyInterest()
    {
        adjust(static_cast<long long>(static_cast<double>(balance()) * m_rate / 100.0 / 12.0));
    }

    bool withdraw(long long cents)
    {
        if (m_withdrawals >= 3 || cents <= 0 || cents > balance())
        {
            return false;
        }
        adjust(-cents);
        ++m_withdrawals;
        return true;
    }

private:
    double m_rate{};
    int m_withdrawals{ 0 };
};

unitTests:
template <typename T> concept CanAdjust = requires(T t) { t.adjust(1LL); };
static_assert(std::is_base_of_v<Account, SavingsAccount>);
static_assert(!CanAdjust<Account> && !CanAdjust<SavingsAccount>, "adjust should be protected");

TEST("deposit") { SavingsAccount s{ 12.0 }; CHECK(s.deposit(100000)); CHECK(!s.deposit(0)); CHECK_EQ(s.balance(), 100000); }
TEST("monthly interest") { SavingsAccount s{ 12.0 }; s.deposit(100000); s.addMonthlyInterest(); CHECK_EQ(s.balance(), 101000); s.addMonthlyInterest(); CHECK_EQ(s.balance(), 102010); }
TEST("only three withdrawals") { SavingsAccount s{ 0.0 }; s.deposit(1000); CHECK(s.withdraw(100)); CHECK(s.withdraw(100)); CHECK(s.withdraw(100)); CHECK(!s.withdraw(100)); CHECK_EQ(s.balance(), 700); }
TEST("failed withdrawals do not use up the allowance") { SavingsAccount s{ 0.0 }; s.deposit(500); CHECK(!s.withdraw(9999)); CHECK(!s.withdraw(-1)); CHECK(s.withdraw(1)); CHECK(s.withdraw(1)); CHECK(s.withdraw(1)); CHECK_EQ(s.balance(), 497); }

